-- v8 migration — Guess the Fake question bank (two truths and a lie).
-- Feeds the Guess the Fake game. Safe to run on live data (idempotent).
--
-- statement_1 & statement_2 are TRUE, statement_3 is the FAKE (fake_index = 3).
-- The app shuffles the three statements each time it shows a round.

create table if not exists gtf_questions (
  id uuid primary key default gen_random_uuid(),
  topic text not null,
  difficulty text not null default 'medium',   -- easy | medium | hard
  testament text,                              -- OT | NT | null
  statement_1 text not null,
  statement_2 text not null,
  statement_3 text not null,
  fake_index int not null default 3,           -- which statement is the lie (1, 2, or 3)
  explanation text,                            -- the correction, for the leader
  active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Unique topic lets the seed below be re-run safely (on conflict do nothing).
create unique index if not exists gtf_questions_topic_key on gtf_questions (topic);
create index if not exists gtf_questions_active_idx on gtf_questions (active, difficulty);

-- RLS disabled to match the other game tables (see game_prompts).
alter table gtf_questions disable row level security;

-- Seed the 85-round bank. Re-running is safe: existing topics are skipped.
on conflict (topic) do nothing;
